        d["Dane pasażera przesyłane ze stacji co noc."] = "Дані пасажирів надходять зі станцій щоночі.";
        d["Data i przyczyna śmierci. Jeśli człowiek przed tobą ma akt zgonu, masz problem albo cud."] = "Дата й причина смерті. Якщо людина перед тобою має акт про смерть, у тебе або проблема, або диво.";
        d["Data urodzenia się nie zgadza"] = "Дата народження не збігається";
        d["Data wydania z przyszłości, podróż po śmierci, urodziny rok później niż w bazie. Daty kłamią najgłośniej."] = "Дата видачі з майбутнього, поїздка після смерті, день народження на рік пізніше, ніж у базі. Дати брешуть найголосніше.";
        d["Decyduj sam"] = "Вирішуй сам";
        d["Decyduj sam. Kolejka się kończy."] = "Вирішуй сам. Черга добігає кінця.";
        d["Decyzja zapisana."] = "Рішення записано.";
        d["Decyzja zapisana. Coś jest nie tak."] = "Рішення записано. Щось не так.";
        d["Dlaczego nie ma pana w bazie?"] = "Чому вас немає в базі?";
        d["Dlaczego pani tu ciągle wraca?"] = "Чому ви сюди постійно повертаєтеся?";
        d["Dobra decyzja."] = "Правильне рішення.";
        d["Dobry wieczór, konduktorze."] = "Добрий вечір, провіднику.";
        d["Dobry wieczór, młody człowieku. Bilet mam, ale głowa nie ta co dawniej."] = "Добрий вечір, юначе. Квиток маю, але голова вже не та, що колись.";
        d["Dobry wieczór. Jadę jak co noc, do stacji 13. Ktoś tam na mnie czeka."] = "Добрий вечір. Їду, як щоночі, до станції 13. Там на мене хтось чекає.";
        d["Dobry wieczór. Jest tu jakoś zimno. Jestem umówiona z córką."] = "Добрий вечір. Тут якось холодно. Я домовилася про зустріч із донькою.";
        d["Dokument należy zwrócić po zgonie właściciela."] = "Після смерті власника документ підлягає поверненню.";
        d["Dokument wydany w przyszłości. Data systemowa niezgodna."] = "Документ виданий у майбутньому. Системна дата не збігається.";
        d["Dokument zmienia tekst"] = "Документ змінює текст";
        d["Dokument zmieniony ręcznie. Dane się nie zgadzają."] = "Документ змінено вручну. Дані не збігаються.";
        d["Dokumenty z przyszłej lub przeszłej daty. Ktoś, kto już tu był albo dopiero będzie. Widzenie ich boli w głowie."] = "Документи з майбутньою або минулою датою. Хтось, хто вже був тут або тільки буде. Від погляду на них болить голова.";
        d["Dokumenty zaczynają mówić o tobie. Data zatrudnienia, numer K-13-0013, zdjęcie, którego nie robiłeś. Inspektor wraca. Człowiek w szarym płaszczu mówi twoje imię, zanim je przeczyta."] = "Документи починають говорити про тебе. Дата прийняття на роботу, номер K-13-0013, фото, якого ти не робив. Інспектор повертається. Чоловік у сірому пальті називає твоє ім’я, ще не прочитавши його.";
        d["Dostałeś pracę konduktora na nocnym pociągu Linii 13. Peron jest mokry, latarnia ciężka, a kolejka cicha. Porównaj bilet, dowód, bazę kolejową i rejestr. Jeśli dane się nie zgadzają, coś jest nie tak. Dokumenty można przeciągać, powiększać i oznaczać. Patrz też na samych ludzi: żywym idzie para z ust i każdy rzuca cień."] = "Ти отримав роботу провідника на нічному поїзді Лінії 13. Перон мокрий, ліхтар важкий, а черга мовчазна. Порівняй квиток, посвідчення, залізничну базу й реєстр. Якщо дані не збігаються, щось не так. Документи можна перетягувати, збільшувати й позначати. Дивись і на самих людей: у живих іде пара з рота, і кожен відкидає тінь.";
        d["Dotrwaj do jedenastej nocy w trybie fabularnym."] = "Дотривай до одинадцятої ночі в сюжетному режимі.";
        d["Dotrwaj do szóstej nocy w trybie fabularnym."] = "Дотривай до шостої ночі в сюжетному режимі.";
        d["Dotrzyj do ukrytego wydarzenia w pociągu."] = "Дістанься прихованої події в поїзді.";
        d["Dowód"] = "Посвідчення";
        d["Druga księga. Zapisano w niej wszystkich, których Dyrekcja wykreśliła. Twoje imię jest na pierwszej stronie."] = "Друга книга. У ній записані всі, кого Дирекція викреслила. Твоє ім’я — на першій сторінці.";
        d["Drugi Rejestr otwiera się w twoich rękach. Wykreśleni wracają na listę jeden po drugim: Anna, Marek, Lena, człowiek bez dokumentów. Ci, którym pomogłeś, czekają w wagonach i robią ci miejsce.\n\nWsiadasz. Pociąg rusza, ale nie w stronę stacji 13. Za peronem 13 jest jeszcze jeden, którego nie ma w żadnym rozkładzie. Na tablicy błyska napis: PASAŻERÓW: 14. Po raz pierwszy liczba się zgadza."] = "Другий Реєстр розкривається в твоїх руках. Викреслені повертаються до списку один за одним: Анна, Марек, Лена, людина без документів. Ті, кому ти допоміг, чекають у вагонах і звільняють для тебе місце.\n\nТи сідаєш. Поїзд рушає, але не до станції 13. За пероном 13 є ще один, якого немає в жодному розкладі. На табло спалахує напис: ПАСАЖИРІВ: 14. Уперше число збігається.";
        d["Dwunastu pasażerów. Potem jeszcze jeden. System pokaże liczbę, która się zgadza z twoim numerem służbowym. Zanim wpuścisz ostatniego, terminal Rejestru zapyta cię o coś jeszcze."] = "Дванадцять пасажирів. Потім ще один. Система покаже число, що збігається з твоїм службовим номером. Перш ніж пропустиш останнього, термінал Реєстру запитає тебе ще про дещо.";
        d["Dyr. J. Zawada"] = "Дир. Я. Завада";
        d["Dyrekcja"] = "Дирекція";
        d["Dyrekcja Kolei"] = "Дирекція залізниці";
        d["Dyrekcja milczy. Radio milczy. Kolejka składa się z twarzy, które już znasz: ludzi, którym pomogłeś, i tych, którym odmówiłeś. Nikt nie ocenia, czy masz rację. Zostajesz z własnym sumieniem i regulaminem, który nikogo już nie obchodzi."] = "Дирекція мовчить. Радіо мовчить. Черга складається з облич, які ти вже знаєш: людей, яким ти допоміг, і тих, кому відмовив. Ніхто не оцінює, чи маєш ти рацію. Ти залишаєшся зі своїм сумлінням і регламентом, до якого нікому нема діла.";
        d["Dyrekcja zmieniła zdanie: zmarli mają prawo do przejazdu. Na peronie robi się zimniej i lampy migają częściej. Do teczki dołącza historia podróży. Zwracaj uwagę na to, co dzieje się ze światłem."] = "Дирекція змінила думку: померлі мають право на проїзд. На пероні холоднішає, а лампи блимають частіше. До теки додається історія поїздок. Звертай увагу на те, що відбувається зі світлом.";
        d["Dyscyplina"] = "Дисципліна";
        d["Dyscyplina "] = "Дисципліна ";
        d["Dziecko, które czeka na mamę. Kolejne noce, ta sama sukienka, to samo pytanie: \"Czy mama już jest w wagonie?\""] = "Дитина, що чекає на маму. Ніч за ніччю та сама сукня, те саме запитання: «А мама вже у вагоні?»";
        d["Dzień dobry. Szukam mamy. Ona jest w pociągu, prawda?"] = "Добрий день. Шукаю маму. Вона в поїзді, правда?";
        d["Dziś jest ten dzień, prawda? Nie boję się. A pan?"] = "Сьогодні той день, правда? Я не боюся. А ви?";
        d["Dziś kończę swoją zmianę. Pan zaczyna swoją. Albo odwrotnie."] = "Сьогодні я закінчую свою зміну. Ви починаєте свою. Або навпаки.";
        d["Dziś przyniosłem tylko jeden zegarek. Pokazuje właściwą godzinę."] = "Сьогодні я приніс лише один годинник. Він показує правильний час.";
