        d["GRUPA KRWI"] = "ГРУПА КРОВІ";
        d["Gdzie jest druga księga?"] = "Де друга книга?";
        d["Gdzie jest mama?"] = "Де мама?";
        d["GŁOŚNOŚĆ GŁÓWNA: "] = "ЗАГАЛЬНА ГУЧНІСТЬ: ";
        d["HISTORIA LINII 13"] = "ІСТОРІЯ ЛІНІЇ 13";
        d["HISTORIA PODRÓŻY"] = "ІСТОРІЯ ПОДОРОЖЕЙ";
        d["HISTORIA PRACY"] = "ІСТОРІЯ РОБОТИ";
        d["Historia obejmuje tylko przejazdy Linią 13."] = "Історія охоплює лише поїздки Лінією 13.";
        d["Historia podróży"] = "Історія поїздок";
        d["IMIĘ I NAZWISKO"] = "ІМ’Я ТА ПРІЗВИЩЕ";
        d["INDEKS ANOMALII"] = "ІНДЕКС АНОМАЛІЙ";
        d["INTEGRALNOŚĆ"] = "ЦІЛІСНІСТЬ";
        d["Imię, data urodzenia, numer dokumentu i zdjęcie. Sprawdzaj zdjęcie, zanim uwierzysz w resztę."] = "Ім’я, дата народження, номер документа й фото. Перевіряй фото, перш ніж повірити решті.";
        d["Inspekcja"] = "Інспекція";
        d["Inspektor Dyrekcji Kolei. Zawsze punktualny, zawsze bez dokumentów. Nikt nie widział, jak wchodzi na peron."] = "Інспектор Дирекції залізниці. Завжди пунктуальний, завжди без документів. Ніхто не бачив, як він виходить на перон.";
        d["Inspektor Kruk"] = "Інспектор Крук";
        d["Inspektor Kruk, Dyrekcja Kolei. Nie muszę okazywać dokumentów, ale okażę."] = "Інспектор Крук, Дирекція залізниці. Я не зобов’язаний показувати документи, але покажу.";
        d["Inspektor podpisał raport i zniknął w mgle. Nikt nie widział, jak wychodzi z peronu. Zostawił po sobie zapach zimnego żelaza."] = "Інспектор підписав звіт і зник у тумані. Ніхто не бачив, як він виходить із перону. Після нього залишився запах холодного заліза.";
        d["Jak długo pani jeździ?"] = "Як довго ви їздите?";
        d["Jak masz na imię?"] = "Як тебе звати?";
        d["Jak się pan nazywa?"] = "Як вас звати?";
        d["Jeden raz. Do stacji 13."] = "Один раз. До станції 13.";
        d["Jest. Zawsze była. Tylko że nie mogłam do niej wejść bez pańskiego pozwolenia."] = "Так. Вона завжди там була. Тільки я не могла до неї зайти без вашого дозволу.";
        d["Jestem tu od zawsze. Czekam na pana."] = "Я тут від початку. Чекаю на вас.";
        d["Jeśli mnie dziś wpuścisz, powiem ci, gdzie leży druga księga."] = "Якщо ти мене сьогодні пропустиш, я скажу тобі, де лежить друга книга.";
        d["Już nic więcej."] = "Більше нічого.";
        d["Już nigdy o nic nie poproszę."] = "Я більше ніколи ні про що не попрошу.";
        d["KARTA MEDYCZNA"] = "МЕДИЧНА КАРТКА";
        d["KASJER"] = "КАСИР";
        d["KODEKS"] = "КОДЕКС";
        d["KOLEJ"] = "ЗАЛІЗНИЦЯ";
        d["KONDUKTOR"] = "ПРОВІДНИК";
        d["KONDUKTOR NIE WSIADŁ"] = "ПРОВІДНИК НЕ СІВ У ПОТЯГ";
        d["KONIEC A: IDEALNY KONDUKTOR"] = "КІНЕЦЬ A: ІДЕАЛЬНИЙ ПРОВІДНИК";
        d["KONIEC A: ZOSTAJESZ"] = "КІНЕЦЬ A: ТИ ЗАЛИШАЄШСЯ";
        d["KONIEC B: ZŁAMANY SYSTEM"] = "КІНЕЦЬ B: ЗЛАМАНА СИСТЕМА";
        d["KONIEC C: PRAWDA"] = "КІНЕЦЬ C: ПРАВДА";
        d["KONIEC D: CZĘŚĆ LINII 13"] = "КІНЕЦЬ D: ЧАСТИНА ЛІНІЇ 13";
        d["KONIEC PORÓWNANIA"] = "ЗАВЕРШИТИ ПОРІВНЯННЯ";
        d["KONIEC: PERON CZTERNASTY"] = "КІНЕЦЬ: ЧОТИРНАДЦЯТИЙ ПЕРОН";
        d["KONTYNUUJ"] = "ПРОДОВЖИТИ";
        d["KREWNI"] = "РОДИЧІ";
        d["Kadłub nie wytrzymał. Linia 13 zatrzymała się na dobre, a peron zapadł w ciszę."] = "Корпус не витримав. Лінія 13 зупинилася назавжди, а перон поринув у тишу.";
        d["Kadłub trzeszczy. Integralność poniżej 30%."] = "Корпус скрипить. Цілісність нижче 30%.";
        d["Karta medyczna"] = "Медична картка";
        d["Karta nie zawiera informacji o pobycie w wagonie 13."] = "У картці немає відомостей про перебування у вагоні 13.";
        d["Każdy konduktor kiedyś skończył zmianę. Żaden nie pamięta, czy wsiadł."] = "Кожен провідник колись закінчив зміну. Жоден не пам’ятає, чи сів у поїзд.";
        d["Każdy prawdziwy człowiek rzuca cień. Jeśli go nie ma, rzeczywistość o nim zapomniała."] = "Кожна справжня людина відкидає тінь. Якщо її немає, дійсність про неї забула.";
        d["Kim pan jest?"] = "Хто ви?";
        d["Klucz. Numer trzynaście. Od zamka, o którym nie powinienem wiedzieć."] = "Ключ. Номер тринадцять. Від замка, про який мені не слід знати.";
        d["Kobieta, która jeździ tym samym pociągiem od trzydziestu lat. Zawsze ma bilet na stację 13 i zawsze mówi, że ktoś tam na nią czeka."] = "Жінка, яка їздить одним і тим самим поїздом уже тридцять років. Завжди має квиток до станції 13 і завжди каже, що на неї там хтось чекає.";
        d["Kodeks zawiera wpis, którego nie widziałeś. Napisano go twoim pismem."] = "У Кодексі є запис, якого ти не бачив. Його написано твоїм почерком.";
        d["Kolej nie odpowiada za osoby bez wpisu."] = "Залізниця не відповідає за осіб, яких немає в реєстрі.";
        d["Kolej zapisuje wszystkie podróże. Zapisuje też te, które się jeszcze nie odbyły."] = "Залізниця записує всі поїздки. Записує й ті, що ще не відбулися.";
        d["Kolejka się skończyła.\n\nPASAŻERÓW POZOSTAŁO: 1\n\nNa peronie stoi jeszcze jedna osoba. Podchodzi do okienka wolno, tak jak się podchodzi do własnego odbicia."] = "Черга скінчилася.\n\nПАСАЖИРІВ ЗАЛИШИЛОСЯ: 1\n\nНа пероні стоїть ще одна особа. Вона підходить до віконця повільно, так, як підходять до власного відображення.";
        d["Kolejna noc za tobą. Peron już czeka."] = "Ще одна ніч позаду. Перон уже чекає.";
        d["Kolejowa"] = "Залізнична";
        d["Konduktor"] = "Провідник";
        d["Konduktor. Pierwszy. Ten, który nie wsiadł."] = "Провідник. Перший. Той, що не сів у поїзд.";
        d["Kontrola. Proszę mnie natychmiast wpuścić, mam rozkaz."] = "Контроль. Прошу негайно мене пропустити, я маю наказ.";
        d["Kruka? Jest zawsze tam, gdzie jest lista. Nigdy nie widziałam, żeby wchodził po schodach."] = "Крука? Він завжди там, де список. Я ніколи не бачила, щоб він ішов сходами.";
        d["Krótka"] = "Коротка";
        d["Kto ci to powiedział?"] = "Хто тобі це сказав?";
        d["Kto na panią czeka?"] = "Хто на вас чекає?";
        d["Kto napisał regulamin?"] = "Хто написав регламент?";
        d["Kto puka?"] = "Хто стукає?";
        d["Ktoś je do mnie powtarza. Co noc, od bardzo dawna."] = "Хтось повторює його мені. Щоночі, вже дуже давно.";
        d["Ktoś powtarza twoje imię. Cicho, za ścianą."] = "Хтось повторює твоє ім’я. Тихо, за стіною.";
        d["Ktoś puka od środka wagonu, którego nikt nie wpuszczał. Pukanie ma zawsze ten sam rytm: trzy, pauza, trzynaście."] = "Хтось стукає зсередини вагона, до якого ніхто не сідав. Стукіт завжди має той самий ритм: три, пауза, тринадцять.";
        d["Ktoś puka od środka wagonu, którego nikt nie wpuszczał. W manifeście go nie ma. W liczniku pasażerów też nie. Dyrekcja zabrania zbliżać się do zamka. Ale klucz od Piotra Wrony leży w twojej kieszeni."] = "Хтось стукає зсередини вагона, до якого ніхто не сідав. У маніфесті його немає. У лічильнику пасажирів теж. Дирекція забороняє наближатися до замка. Але ключ Пйотра Врони лежить у твоїй кишені.";
        d["Ktoś sprzedaje bilety na cudze nazwiska. Sprawdzaj, czy imię na bilecie zgadza się z dowodem, a pieczęć jest z właściwej stacji. Od dziś masz też manifest: listę osób, które mają dziś jechać."] = "Хтось продає квитки на чужі імена. Перевіряй, чи ім’я на квитку збігається з посвідченням, а печатка — з правильної станції. Відтепер у тебе є й маніфест: список осіб, які мають їхати сьогодні.";
        d["Ktoś używa cudzych dokumentów. Zdjęcie na dowodzie nie zgadza się z twarzą, a podpis jest odrobinę za równy."] = "Хтось користується чужими документами. Фото на посвідченні не збігається з обличчям, а підпис трохи занадто рівний.";
        d["Ktoś z kolejki znika i nikt nie zauważa, że go nie ma. Nikt oprócz ciebie."] = "Хтось із черги зникає, і ніхто не помічає його відсутності. Ніхто, крім тебе.";
        d["Która jest godzina?"] = "Котра година?";
        d["Który z nas jest prawdziwy?"] = "Хто з нас справжній?";
        d["Któryś z nieistniejących powiedział na odchodnym: \"Dziękuję, że pan mnie zobaczył\". Nie wiesz, czy to była groźba."] = "Хтось із неіснуючих сказав на прощання: «Дякую, що ви мене побачили». Ти не знаєш, чи це була погроза.";
        d["LEKARZ"] = "ЛІКАР";
        d["LICZBA PODRÓŻY"] = "КІЛЬКІСТЬ ПОДОРОЖЕЙ";
        d["LINIA 13"] = "ЛІНІЯ 13";
        d["LISTA NOCNA"] = "НІЧНИЙ СПИСОК";
        d["LUDZIE"] = "ЛЮДИ";
        d["Lena"] = "Лена";
        d["Lena. Wolska. Tak jak mama."] = "Лена. Вольська. Так само, як мама.";
        d["Liczba pasażerów: 14."] = "Кількість пасажирів: 14.";
        d["Linia 13"] = "Лінія 13";
